const sensorId = msg.sensorId;
if (!sensorId) return null;

const datos = msg.payload[sensorId];
if (!datos) return null;

const limiteSup = global.get('limiteSupHumSustrato');
const limiteInf = global.get('limiteInfHumSustrato');

// Cooldown propio para no repetir la misma alerta a cada rato.
// Independiente de tiempoEnfriamientoMin (ese es para el riego automático, no para avisos).
const COOLDOWN_MIN = 30;

let alertasEnviadas = global.get('alertasEnviadas') || {};
const ahora = Date.now();

function yaEnviada(tipo) {
    const key = sensorId + '_' + tipo;
    const ultima = alertasEnviadas[key];
    return ultima && (ahora - ultima) < COOLDOWN_MIN * 60 * 1000;
}

function marcarEnviada(tipo) {
    alertasEnviadas[sensorId + '_' + tipo] = ahora;
    global.set('alertasEnviadas', alertasEnviadas);
}

function fechaHora() {
    return new Date(ahora).toLocaleString('es-GT', {
        timeZone: 'America/Guatemala',
        dateStyle: 'short',
        timeStyle: 'medium'
    });
}

let mensajes = [];

if (typeof datos.humedad === 'number') {
    if (datos.humedad > limiteSup && !yaEnviada('humedad_alta')) {
        mensajes.push(`⚠️ Sensor ${sensorId}: humedad de sustrato ALTA (${datos.humedad}%, límite ${limiteSup}%)\n ${fechaHora()}`);
        marcarEnviada('humedad_alta');
    } else if (datos.humedad < limiteInf && !yaEnviada('humedad_baja')) {
        mensajes.push(`⚠️ Sensor ${sensorId}: humedad de sustrato BAJA (${datos.humedad}%, límite ${limiteInf}%)\n ${fechaHora()}`);
        marcarEnviada('humedad_baja');
    }
}

if (datos.bateriaBaja && !yaEnviada('bateria_baja')) {
    mensajes.push(`🔋 Sensor ${sensorId}: batería baja (${datos.bateria}%)\n ${fechaHora()}`);
    marcarEnviada('bateria_baja');
}

if (mensajes.length === 0) return null;

return [mensajes.map(texto => ({
    payload: { chatId: 8444938703, type: 'message', content: texto }
}))];

const sensores = msg.payload;
const id = msg.sensorId;
if (!id || !sensores[id]) return null;

const ahora = Date.now();
const ventanaMs = 60 * 60 * 1000;

let historial = global.get('historialGraficaLora') || {};
let arr = historial[id] || [];

arr.push({ t: ahora, v: sensores[id].humedad });
arr = arr.filter(function(p){ return (ahora - p.t) <= ventanaMs; });
if (arr.length > 300) arr = arr.slice(arr.length - 300);

historial[id] = arr;
global.set('historialGraficaLora', historial);
return null;

const sensores = global.get('sensoresLora') || {};
const valores = Object.values(sensores)
    .map(s => s.humedad)
    .filter(v => typeof v === 'number' && !isNaN(v));

if (valores.length === 0) return null;

const promedio = valores.reduce((a, b) => a + b, 0) / valores.length;

msg.payload = Math.round(promedio * 10) / 10;
return msg;

msg.payload = {
    sensores: global.get('sensoresLora') || {},
    historialPromedio: global.get('historialGraficaPromedio') || [],
    historialSensores: global.get('historialGraficaLora') || {},
    limiteInf: global.get('limiteInfHumSustrato'),
    limiteSup: global.get('limiteSupHumSustrato')
};
if (typeof msg.payload.limiteInf !== 'number') msg.payload.limiteInf = 25;
if (typeof msg.payload.limiteSup !== 'number') msg.payload.limiteSup = 70;
return msg;

const promedio = msg.payload;
const ahora = Date.now();
const ventanaMs = 60 * 60 * 1000;

let arr = global.get('historialGraficaPromedio') || [];
arr.push({ t: ahora, v: promedio });
arr = arr.filter(function(p){ return (ahora - p.t) <= ventanaMs; });
if (arr.length > 300) arr = arr.slice(arr.length - 300);

global.set('historialGraficaPromedio', arr);
return null;

const sensores = global.get('sensoresLora') || {};
const valores = Object.values(sensores)
    .map(s => s.humedad)
    .filter(v => typeof v === 'number' && !isNaN(v));

if (valores.length === 0) return null;

const promedio = valores.reduce((a, b) => a + b, 0) / valores.length;

msg.payload = Math.round(promedio * 10) / 10;
return msg;

node.warn('modoSimulacion = ' + global.get('modoSimulacion'));
if (!global.get('modoSimulacion')) return [null, null];

const msgsLora = [];
for (let i = 1; i <= 6; i++) {
    msgsLora.push({
        topic: 'orquideario/lora/' + i,
        payload: {
            humedad: Math.round(30 + Math.random() * 15),
            bateria: Math.round(60 + Math.random() * 40)
        }
    });
}

const msgAmbiental = {
    topic: 'orquideario/ambiental',
    payload: {
        temperatura: Math.round((22 + Math.random() * 6) * 10) / 10,
        humedad: Math.round(40 + Math.random() * 20)
    }
};

return [msgsLora, [msgAmbiental]];

// Espera dos formatos posibles de payload:
// A) Real (Heltec Receptor): { id, soil, hum, temp, bat, rssi, snr } — valores CRUDOS, sin calibrar
// B) Simulado (modoSimulacion=true): { humedad, bateria } — ya en porcentaje, listo para usar
const partes = msg.topic.split('/');
const sensorId = partes[partes.length - 1];

// ============================================================
// CALIBRACION DE HUMEDAD — un par SOIL_SECO/SOIL_MOJADO por sensor,
// medido en campo el 5-6 de septiembre 2026 (aire = seco, agua = mojado).
// Cada sensor tiene su propia pequeña variacion de fabricacion, por eso
// se calibra individualmente en vez de usar una sola constante para los 6.
// ============================================================
const CALIBRACION_SOIL = {
    "1": { seco: 886, mojado: 660 },  // ID012101
    "2": { seco: 883, mojado: 677 },  // ID012129
    "3": { seco: 888, mojado: 624 },  // ID012097
    "4": { seco: 883, mojado: 653 },  // ID012127
    "5": { seco: 879, mojado: 618 },  // ID012107
    "6": { seco: 883, mojado: 680 },  // ID012096
};

// Calibracion de bateria — TODAVIA PENDIENTE, usa placeholders genericos
// para los 6 sensores por igual hasta que se haga la prueba real
// (bateria nueva / bateria casi agotada) para cada uno.
const BAT_VACIA = 700;
const BAT_LLENA = 1000;

function aPorcentaje(valor, desde, hasta) {
    if (typeof valor !== 'number' || isNaN(valor)) return null;
    const pct = ((valor - desde) / (hasta - desde)) * 100;
    return Math.max(0, Math.min(100, Math.round(pct * 10) / 10));
}

// Umbral de aviso: por debajo de este % de bateria, la lectura de humedad
// de ESE sensor puede no ser confiable (bajo voltaje distorsiona el ADC
// capacitivo, no solo afecta la transmision).
const UMBRAL_BATERIA_BAJA = 20;

let humedad, bateria, idHardware;

if (msg.payload && typeof msg.payload.soil === 'number') {
    // Dato real del Heltec Receptor: soil/bat vienen crudos, hay que calibrar
    const cal = CALIBRACION_SOIL[sensorId];
    if (cal) {
        humedad = aPorcentaje(msg.payload.soil, cal.seco, cal.mojado);
    } else {
        node.warn('Sensor ' + sensorId + ' sin calibracion de humedad definida, se descarta el dato de soil');
        humedad = null;
    }
    bateria = aPorcentaje(msg.payload.bat, BAT_VACIA, BAT_LLENA);
    idHardware = msg.payload.id || null;
} else if (msg.payload && typeof msg.payload.humedad !== 'undefined') {
    // Dato simulado: ya viene en porcentaje, se usa tal cual (sin ID de hardware real)
    humedad = Number(msg.payload.humedad);
    bateria = msg.payload.bateria !== undefined ? Number(msg.payload.bateria) : null;
    idHardware = null;
} else {
    node.warn('Mensaje del sensor LoRa ' + sensorId + ' sin campos reconocibles (ni soil ni humedad), se descarta');
    return null;
}

// Si la bateria esta baja, la lectura de humedad de ESTE sensor puede no
// ser confiable (no es solo un aviso de "cambiar pronto la bateria").
const bateriaBaja = (bateria !== null && bateria < UMBRAL_BATERIA_BAJA);

let sensores = global.get('sensoresLora') || {};
sensores[sensorId] = {
    humedad: humedad,
    bateria: bateria,
    bateriaBaja: bateriaBaja,
    idHardware: idHardware,
    ultimaLectura: Date.now()
};
global.set('sensoresLora', sensores);

msg.payload = sensores;
msg.sensorId = sensorId;
return msg;

// Espera JSON: { "temperatura": <°C>, "humedad": <0-100> }
if (!msg.payload || typeof msg.payload.temperatura === 'undefined' || typeof msg.payload.humedad === 'undefined') {
    node.warn('Mensaje del sensor ambiental incompleto, se descarta');
    return null;
}

const dato = {
    temperatura: Number(msg.payload.temperatura),
    humedad: Number(msg.payload.humedad),
    ultimaLectura: Date.now()
};
global.set('ambiental', dato);

msg.payload = dato;
return msg;

const dato = msg.payload;
return [
    { payload: dato.temperatura },
    { payload: dato.humedad }
];

// Máximo 1 punto por minuto, para que la gráfica se vea como tendencia
// y no como ruido (misma lógica que en Sensores LoRa).
const minIntervaloMs = 60 * 1000;
const ultimo = global.get('ultimoPuntoGraficaAmbTemp') || 0;
const ahora = Date.now();

if (ahora - ultimo < minIntervaloMs) return null;

global.set('ultimoPuntoGraficaAmbTemp', ahora);
return { topic: 'Temperatura', payload: msg.payload };

const minIntervaloMs = 60 * 1000;
const ultimo = global.get('ultimoPuntoGraficaAmbHum') || 0;
const ahora = Date.now();

if (ahora - ultimo < minIntervaloMs) return null;

global.set('ultimoPuntoGraficaAmbHum', ahora);
return { topic: 'Humedad', payload: msg.payload };

function evaluarSostenido(id, activaAhora) {
    const estados = context.get('estados') || {};
    let estado = estados[id] || { startTime: null, activa: false };
    const tiempoMin = global.get('limiteTiempoMin') || 15;
    const tiempoMs = tiempoMin * 60 * 1000;
    const ahora = Date.now();
    const estabaActiva = estado.activa;

    if (!activaAhora) {
        estado = { startTime: null, activa: false };
    } else if (estado.activa) {
        // ya confirmada, se mantiene mientras la condición siga
    } else if (!estado.startTime) {
        estado.startTime = ahora;
    } else if ((ahora - estado.startTime) >= tiempoMs) {
        estado.activa = true;
    }

    estados[id] = estado;
    context.set('estados', estados);

    let transicion = null;
    if (!estabaActiva && estado.activa) transicion = 'entrada';
    if (estabaActiva && !estado.activa) transicion = 'salida';

    let estadoTexto;
    if (estado.activa) {
        estadoTexto = 'alerta';
    } else if (activaAhora) {
        estadoTexto = 'vigilando';
    } else {
        estadoTexto = 'normal';
    }

    return { activa: estado.activa, estadoTexto: estadoTexto, transicion: transicion };
}

function registrarHistorial(titulo, detalle, transicion) {
    if (!transicion) return;
    let historial = global.get('historialAlertas') || [];
    historial.unshift({
        fecha: new Date().toLocaleString('es-GT'),
        titulo: titulo,
        evento: transicion === 'entrada' ? 'Activada' : 'Resuelta',
        detalle: detalle
    });
    if (historial.length > 200) historial = historial.slice(0, 200);
    global.set('historialAlertas', historial);
}

const ambiental = global.get('ambiental') || {};
const sensores = global.get('sensoresLora') || {};

const limiteSupTemp = global.get('limiteSupTemp') ?? 28;
const limiteInfHumAmb = global.get('limiteInfHumAmb') ?? 40;
const limiteSupHumAmb = global.get('limiteSupHumAmb') ?? 80;
const limiteInfHumSustrato = global.get('limiteInfHumSustrato') ?? 25;
const limiteSupHumSustrato = global.get('limiteSupHumSustrato') ?? 70;
const umbralDesviacion = global.get('umbralDesviacionSensor') ?? 15;

const alertas = [];

function evaluarRegla(titulo, activaCondicion, detalle, idRegla) {
    const resultado = evaluarSostenido(idRegla, activaCondicion);
    registrarHistorial(titulo, detalle, resultado.transicion);
    alertas.push({ titulo: titulo, activa: resultado.activa, estado: resultado.estadoTexto, detalle: detalle });
}

// --- Temperatura ambiente ---
if (ambiental.temperatura !== undefined) {
    evaluarRegla(
        'Temperatura ambiente elevada',
        ambiental.temperatura > limiteSupTemp,
        ambiental.temperatura.toFixed(1) + '°C (límite ' + limiteSupTemp + '°C)',
        'temp_alta'
    );
}

// --- Humedad ambiente ---
if (ambiental.humedad !== undefined) {
    evaluarRegla(
        'Humedad ambiente fuera de rango',
        ambiental.humedad < limiteInfHumAmb || ambiental.humedad > limiteSupHumAmb,
        ambiental.humedad.toFixed(1) + '% (rango ' + limiteInfHumAmb + '–' + limiteSupHumAmb + '%)',
        'hum_amb_rango'
    );
}

// --- Humedad de sustrato: UN solo chequeo combinado por sensor ---
const ids = Object.keys(sensores).sort(function(a, b) { return Number(a) - Number(b); });

ids.forEach(function(id) {
    const s = sensores[id];
    if (s.humedad === undefined) return;

    const otros = ids.filter(function(otroId) { return otroId !== id; })
        .map(function(otroId) { return sensores[otroId].humedad; })
        .filter(function(v) { return typeof v === 'number'; });

    const promedioOtros = otros.length > 0 ? otros.reduce(function(a, b) { return a + b; }, 0) / otros.length : null;
    const diferencia = promedioOtros !== null ? Math.abs(s.humedad - promedioOtros) : 0;

    const problemas = [];
    if (s.humedad < limiteInfHumSustrato) {
        problemas.push('muy seco (mínimo ' + limiteInfHumSustrato + '%)');
    }
    if (s.humedad > limiteSupHumSustrato) {
        problemas.push('exceso de agua (máximo ' + limiteSupHumSustrato + '%)');
    }
    if (promedioOtros !== null && diferencia > umbralDesviacion) {
        problemas.push('distinto al resto (promedio de los demás ' + promedioOtros.toFixed(1) + '%)');
    }

    const activaCondicion = problemas.length > 0;
    const detalle = activaCondicion
        ? s.humedad.toFixed(1) + '% — ' + problemas.join('; ')
        : s.humedad.toFixed(1) + '% — dentro de rango, consistente con el resto';

    evaluarRegla('Sensor ' + id + ' — humedad de sustrato', activaCondicion, detalle, 'sustrato_' + id);
});

// Guardo el resultado para que otras páginas (como Resumen) lo puedan
// leer directo, sin tener que repetir todo este cálculo
global.set('ultimasAlertas', alertas);

msg.payload = alertas;
return msg;

const historial = global.get('historialAlertas') || [];
msg.payload = historial;
return msg;

global.set('historialAlertas', []);
msg.payload = [];
return msg;

const sensores = global.get('sensoresLora') || {};
const ambiental = global.get('ambiental') || {};
const alertas = global.get('ultimasAlertas') || [];
const estadoValvula = global.get('estadoValvula') || {};
const modoOperacion = global.get('modoOperacion') || 'automatico';

const valoresHumedad = Object.values(sensores).map(function(s){ return s.humedad; }).filter(function(v){ return typeof v === 'number'; });
const promedioHumedad = valoresHumedad.length > 0 ? (valoresHumedad.reduce(function(a, b){ return a + b; }, 0) / valoresHumedad.length) : null;

const ahora = Date.now();
const sensoresConectados = Object.values(sensores).filter(function(s){
    return s.ultimaLectura && (ahora - s.ultimaLectura) < 5 * 60 * 1000;
}).length;

const alertasActivas = alertas.filter(function(a){ return a.estado === 'alerta'; }).length;
const alertasVigilando = alertas.filter(function(a){ return a.estado === 'vigilando'; }).length;

function pushHistorial(clave, valor) {
    if (valor === null || valor === undefined || isNaN(valor)) {
        return global.get(clave) || [];
    }
    let hist = global.get(clave) || [];
    hist.push(valor);
    if (hist.length > 30) hist.shift();
    global.set(clave, hist);
    return hist;
}

const sparkHumedad = pushHistorial('sparkHumedadSustrato', promedioHumedad);
const sparkTemp = pushHistorial('sparkTemperatura', ambiental.temperatura);
const sparkHumAmb = pushHistorial('sparkHumedadAmb', ambiental.humedad);

// Comparo cada valor contra los límites configurados en Configuración,
// para decirle al usuario directamente si está bien o mal -- no lo dejo
// que tenga que hacer la cuenta mental él mismo.
const limiteInfHumSustrato = global.get('limiteInfHumSustrato') ?? 25;
const limiteSupHumSustrato = global.get('limiteSupHumSustrato') ?? 70;
const limiteSupTemp = global.get('limiteSupTemp') ?? 28;
const limiteInfHumAmb = global.get('limiteInfHumAmb') ?? 40;
const limiteSupHumAmb = global.get('limiteSupHumAmb') ?? 80;

function estadoSustrato() {
    if (promedioHumedad === null) return { texto: 'Sin datos', ok: null };
    if (promedioHumedad < limiteInfHumSustrato) return { texto: 'Bajo el límite', ok: false };
    if (promedioHumedad > limiteSupHumSustrato) return { texto: 'Exceso de agua', ok: false };
    return { texto: 'Dentro de rango', ok: true };
}

function estadoTemp() {
    if (ambiental.temperatura === undefined) return { texto: 'Sin datos', ok: null };
    if (ambiental.temperatura > limiteSupTemp) return { texto: 'Por encima del límite', ok: false };
    return { texto: 'Dentro de rango', ok: true };
}

function estadoHumAmb() {
    if (ambiental.humedad === undefined) return { texto: 'Sin datos', ok: null };
    if (ambiental.humedad < limiteInfHumAmb || ambiental.humedad > limiteSupHumAmb) return { texto: 'Fuera de rango', ok: false };
    return { texto: 'Dentro de rango', ok: true };
}

msg.payload = {
    promedioHumedad: promedioHumedad,
    temperatura: ambiental.temperatura,
    humedadAmb: ambiental.humedad,
    sensoresConectados: sensoresConectados,
    totalSensores: 6,
    alertasActivas: alertasActivas,
    alertasVigilando: alertasVigilando,
    valvulaAbierta: estadoValvula.abierta || false,
    valvulaMotivo: estadoValvula.motivo || 'Sin actividad todavía',
    modoOperacion: modoOperacion,
    sparkHumedad: sparkHumedad,
    sparkTemp: sparkTemp,
    sparkHumAmb: sparkHumAmb,
    estadoSustrato: estadoSustrato(),
    estadoTemp: estadoTemp(),
    estadoHumAmb: estadoHumAmb()
};
return msg;

const cambios = msg.payload || {};
Object.keys(cambios).forEach(function(clave){
    global.set(clave, cambios[clave]);
});
return null;

const defaults = {
    modoOperacion: 'automatico',
    modoSimulacion: false,
    limiteSupTemp: 28,
    limiteTiempoMin: 15,
    limiteInfHumAmb: 40,
    limiteSupHumAmb: 80,
    limiteInfHumSustrato: 25,
    limiteSupHumSustrato: 70,
    umbralDesviacionSensor: 15,
    duracionRiegoSeg: 30,
    tiempoEnfriamientoMin: 60,
    tiempoMaxAperturaSeg: 180
};
Object.keys(defaults).forEach(function(clave){
    if (global.get(clave) === undefined) {
        global.set(clave, defaults[clave]);
    }
});

const limites = {
    limiteSupTemp: global.get('limiteSupTemp'),
    limiteTiempoMin: global.get('limiteTiempoMin'),
    limiteInfHumAmb: global.get('limiteInfHumAmb'),
    limiteSupHumAmb: global.get('limiteSupHumAmb'),
    limiteInfHumSustrato: global.get('limiteInfHumSustrato'),
    limiteSupHumSustrato: global.get('limiteSupHumSustrato'),
    umbralDesviacionSensor: global.get('umbralDesviacionSensor'),
    duracionRiegoSeg: global.get('duracionRiegoSeg'),
    tiempoEnfriamientoMin: global.get('tiempoEnfriamientoMin'),
    tiempoMaxAperturaSeg: global.get('tiempoMaxAperturaSeg')
};

return [
    { payload: global.get('modoOperacion') === 'automatico' },
    { payload: global.get('modoSimulacion') },
    { payload: limites }
];

const modoOperacion = global.get('modoOperacion') || 'automatico';
const sensores = global.get('sensoresLora') || {};
const limiteInfHumSustrato = global.get('limiteInfHumSustrato') ?? 25;
const duracionRiegoSeg = global.get('duracionRiegoSeg') ?? 30;
const tiempoEnfriamientoMin = global.get('tiempoEnfriamientoMin') ?? 60;
const tiempoMaxAperturaSeg = global.get('tiempoMaxAperturaSeg') ?? 180;

const ahora = Date.now();
let estado = global.get('estadoValvula') || { abierta: false, origen: null, inicioApertura: null, ultimoCierre: null, motivo: 'Sin actividad todavía' };

// 1) Seguridad: cierre forzado si excede el tiempo máximo, sin importar modo u origen
if (estado.abierta && estado.inicioApertura && (ahora - estado.inicioApertura) >= tiempoMaxAperturaSeg * 1000) {
    estado.abierta = false;
    estado.ultimoCierre = ahora;
    estado.motivo = 'Cerrada por seguridad (superó ' + tiempoMaxAperturaSeg + 's abierta)';
    estado.origen = null;
}

// 2) Cierre normal del riego automático al cumplir la duración configurada
if (estado.abierta && estado.origen === 'automatico' && estado.inicioApertura && (ahora - estado.inicioApertura) >= duracionRiegoSeg * 1000) {
    estado.abierta = false;
    estado.ultimoCierre = ahora;
    estado.motivo = 'Riego automático completado (' + duracionRiegoSeg + 's)';
    estado.origen = null;
}

// 3) Disparo automático si corresponde
if (modoOperacion === 'automatico' && !estado.abierta) {
    const valores = Object.values(sensores).map(function(s){ return s.humedad; }).filter(function(v){ return typeof v === 'number'; });
    if (valores.length > 0) {
        const promedio = valores.reduce(function(a, b){ return a + b; }, 0) / valores.length;
        const enEnfriamiento = estado.ultimoCierre && (ahora - estado.ultimoCierre) < tiempoEnfriamientoMin * 60 * 1000;

        if (promedio < limiteInfHumSustrato && !enEnfriamiento) {
            estado.abierta = true;
            estado.origen = 'automatico';
            estado.inicioApertura = ahora;
            estado.motivo = 'Riego automático — promedio ' + promedio.toFixed(1) + '% bajo el límite ' + limiteInfHumSustrato + '%';
        }
    }
}

global.set('estadoValvula', estado);

msg.payload = Object.assign({}, estado, { modoOperacion: modoOperacion });
return msg;

const modoOperacion = global.get('modoOperacion') || 'automatico';

if (modoOperacion !== 'manual') {
    node.warn('Comando manual ignorado: el sistema está en modo automático');
    return null;
}

let estado = global.get('estadoValvula') || { abierta: false, origen: null, inicioApertura: null, ultimoCierre: null, motivo: '' };
const ahora = Date.now();

if (msg.payload === 'abrir') {
    estado.abierta = true;
    estado.origen = 'manual';
    estado.inicioApertura = ahora;
    estado.motivo = 'Abierta manualmente';
} else if (msg.payload === 'cerrar') {
    estado.abierta = false;
    estado.origen = null;
    estado.ultimoCierre = ahora;
